import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
`);
if (!database.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
const listProjects = database.prepare(`
  SELECT projects.id, projects.name, projects.archived,
    COUNT(tasks.id) AS total, COALESCE(SUM(tasks.completed), 0) AS completed
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
  WHERE projects.archived = ? GROUP BY projects.id ORDER BY projects.id
`);
const findProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const setArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const taskPriorities = ['Low', 'Normal', 'High'];
const setTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?');

function projectFilter(value) {
  return value === 'Archived' ? 'Archived' : 'Active';
}

function taskFilter(value) {
  return ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #f4f6fa; color: #1c293d; font: 16px system-ui, sans-serif; }
    main { max-width: 760px; margin: 60px auto; padding: 28px; background: white; border-radius: 12px; }
    h1 { margin-top: 0; overflow-wrap: anywhere; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    input { padding: 10px; border: 1px solid #798496; border-radius: 5px; font: inherit; width: 100%; }
    button { padding: 10px 16px; border: 0; border-radius: 5px; background: #244ecb; color: white; font: inherit; cursor: pointer; }
    button:hover { background: #193aa0; }
    :focus-visible { outline: 3px solid #e99500; outline-offset: 3px; }
    .create button { margin-top: 12px; }
    .projects, .tasks { margin-top: 30px; }
    .task { border-top: 1px solid #dce1e9; padding: 16px 0; overflow-wrap: anywhere; }
    .task label { display: flex; align-items: center; gap: 12px; margin: 0; }
    input[type="checkbox"] { width: auto; flex-shrink: 0; }
    .filter { margin-top: 24px; }
    select { padding: 8px; font: inherit; }
    .create { margin-top: 24px; }
    .project { display: flex; align-items: center; justify-content: space-between; gap: 20px; border-top: 1px solid #dce1e9; padding: 16px 0; }
    .project span { overflow-wrap: anywhere; min-width: 0; }
    .project form { flex-shrink: 0; }
    .project { flex-wrap: wrap; }
    button:disabled, input:disabled, select:disabled { cursor: not-allowed; opacity: 0.6; }
    [role="alert"] { color: #a21d26; margin: 14px 0; }
    @media (max-width: 600px) { main { margin: 20px 12px; padding: 20px; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function projectsPage(error = '', filter = 'Active') {
  const projects = listProjects.all(filter === 'Archived' ? 1 : 0);
  return page('Projects', `
    <h1>Workboard</h1>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create" method="post" action="/projects">
      <input type="hidden" name="filter" value="${filter}">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text">
      <button type="submit">Create project</button>
    </form>
    <form class="filter" method="get" action="/">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['Active', 'Archived'].map(option => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <section class="projects" aria-label="Projects">
      ${projects.map(project => `<div class="project" data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <span data-testid="project-summary">${project.completed}/${project.total} completed</span>
        <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
        <form method="post" action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}"><button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button></form>
      </div>`).join('')}
    </section>`);
}

function projectPage(project, filter = 'All', error = '') {
  const tasks = listTasks.all(project.id).filter(task =>
    filter === 'All' || Boolean(task.completed) === (filter === 'Completed'));
  return page(project.name, `
    <h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form method="get" action="/"><button type="submit">Projects</button></form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create" method="post" action="/projects/${project.id}/rename">
      <input type="hidden" name="filter" value="${filter}">
      <label for="new-project-name">New project name</label>
      <input id="new-project-name" name="name" type="text"${project.archived ? ' disabled' : ''}>
      <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
    </form>
    <form class="create" method="post" action="/projects/${project.id}/tasks">
      <input type="hidden" name="filter" value="${filter}">
      <label for="task-title">Task title</label>
      <input id="task-title" name="title" type="text">
      <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
    </form>
    <form class="filter" method="get" action="/projects/${project.id}">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['All', 'Open', 'Completed'].map(option => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <section class="tasks" aria-label="Tasks">
      ${tasks.map(task => `<div class="task" data-testid="task-row">
        <form method="post" action="/projects/${project.id}/tasks/${task.id}">
          <input type="hidden" name="filter" value="${filter}">
          <label><input type="checkbox" name="completed" value="1" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()"><span>${escapeHtml(task.title)}</span></label>
        </form>
        <form class="filter" method="post" action="/projects/${project.id}/tasks/${task.id}/priority">
          <input type="hidden" name="filter" value="${filter}">
          <label for="task-priority-${task.id}">Task priority</label>
          <select id="task-priority-${task.id}" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
            ${taskPriorities.map(priority => `<option${task.priority === priority ? ' selected' : ''}>${priority}</option>`).join('')}
          </select>
        </form>
        <form class="create" method="post" action="/projects/${project.id}/tasks/${task.id}/rename">
          <input type="hidden" name="filter" value="${filter}">
          <label for="new-task-title-${task.id}">New task title</label>
          <input id="new-task-title-${task.id}" name="title" type="text"${project.archived ? ' disabled' : ''}>
          <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
        </form>
      </div>`).join('')}
    </section>`);
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && url.pathname === '/') {
      sendHtml(response, 200, projectsPage('', projectFilter(url.searchParams.get('filter'))));
    } else if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 200, projectsPage('Project name is required', projectFilter(form.get('filter'))));
        return;
      }
      createProject.run(name);
      response.writeHead(303, { Location: '/' });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/\d+\/rename$/.test(url.pathname)) {
      const projectId = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(projectId) ? findProject.get(projectId) : null;
      if (!project) {
        sendHtml(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      if (project.archived) {
        sendHtml(response, 403, projectPage(project, filter, 'Archived projects cannot be changed'));
        return;
      }
      const name = (form.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 200, projectPage(project, filter, 'Project name is required'));
        return;
      }
      renameProject.run(name, projectId);
      response.writeHead(303, { Location: `/projects/${projectId}?filter=${filter}` });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/\d+\/(archive|restore)$/.test(url.pathname)) {
      const [, , id, action] = url.pathname.split('/');
      const projectId = Number(id);
      const project = Number.isSafeInteger(projectId) ? findProject.get(projectId) : null;
      if (!project) {
        sendHtml(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      setArchived.run(action === 'archive' ? 1 : 0, projectId);
      response.writeHead(303, { Location: action === 'archive' ? '/' : '/?filter=Archived' });
      response.end();
    } else if (request.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
      const id = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : null;
      if (!project) {
        sendHtml(response, 404, page('Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
        return;
      }
      sendHtml(response, 200, projectPage(project, taskFilter(url.searchParams.get('filter'))));
    } else if (request.method === 'POST' && /^\/projects\/\d+\/tasks(?:\/\d+(?:\/(?:rename|priority))?)?$/.test(url.pathname)) {
      const parts = url.pathname.split('/');
      const projectId = Number(parts[2]);
      const project = Number.isSafeInteger(projectId) ? findProject.get(projectId) : null;
      if (!project) {
        sendHtml(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      if (project.archived) {
        sendHtml(response, 403, projectPage(project, filter, 'Archived projects cannot be changed'));
        return;
      }
      if (parts[4]) {
        const taskId = Number(parts[4]);
        const isRename = parts[5] === 'rename';
        const isPriority = parts[5] === 'priority';
        const priority = form.get('priority');
        if (isPriority && !taskPriorities.includes(priority)) {
          sendHtml(response, 400, projectPage(project, filter, 'Invalid task priority'));
          return;
        }
        const title = (form.get('title') || '').trim();
        if (isRename && !title) {
          sendHtml(response, 200, projectPage(project, filter, 'Task title is required'));
          return;
        }
        const result = Number.isSafeInteger(taskId)
          ? (isRename
            ? renameTask.run(title, taskId, projectId)
            : isPriority
              ? setTaskPriority.run(priority, taskId, projectId)
              : updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, projectId))
          : { changes: 0 };
        if (!result.changes) {
          sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
      } else {
        const title = (form.get('title') || '').trim();
        if (!title) {
          sendHtml(response, 200, projectPage(project, filter, 'Task title is required'));
          return;
        }
        createTask.run(projectId, title);
      }
      response.writeHead(303, { Location: `/projects/${projectId}?filter=${filter}` });
      response.end();
    } else {
      sendHtml(response, 404, page('Not found', '<h1>Page not found</h1>'));
    }
  } catch (error) {
    console.error(error);
    if (!response.headersSent) {
      sendHtml(response, error.status || 500, page('Error', '<h1>Unable to complete request</h1>'));
    } else {
      response.end();
    }
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => {
    database.close();
    process.exit(0);
  }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { createServer } from 'node:net';
import { mkdtemp, mkdir, rm } from 'node:fs/promises';
import { resolve } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

test('projects validate, navigate, escape HTML, and persist across restarts', async () => {
  await mkdir('data', { recursive: true });
  const directory = await mkdtemp('data/test-');
  // Simulate a database from before archive support to verify migration.
  const legacy = new DatabaseSync(resolve(directory, 'projects.sqlite'));
  legacy.exec('CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
  legacy.close();
  const socket = createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const port = socket.address().port;
  await new Promise(resolve => socket.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let child;
  let logs = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: resolve(directory, 'projects.sqlite') },
      stdio: ['ignore', 'pipe', 'pipe']
    });
    child.stdout.on('data', chunk => { logs += chunk; });
    child.stderr.on('data', chunk => { logs += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      try {
        const response = await fetch(`${base}/health`);
        assert.equal(response.status, 200);
        assert.deepEqual(await response.json(), { status: 'ok' });
        return;
      } catch {
        if (child.exitCode !== null) throw new Error(logs);
        await new Promise(resolve => setTimeout(resolve, 30));
      }
    }
    throw new Error(`Server did not become ready: ${logs}`);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/projects`, {
      method: 'POST', body: new URLSearchParams({ name }), redirect: 'manual'
    });
  }
  try {
    await start();
    let html = await (await fetch(base)).text();
    assert.match(html, /<h1>Workboard<\/h1>/);
    assert.match(html, /<label for="project-name">Project name<\/label>/);
    assert.match(html, /Create project/);
    assert.match(html, /<label for="project-filter">Project filter<\/label>/);
    assert.match(html, /<option selected>Active<\/option><option>Archived<\/option>/);
    assert.doesNotMatch(html, /data-testid="project-row"/);
    for (const name of ['', '  \t\n ']) {
      const response = await create(name);
      html = await response.text();
      assert.match(html, /role="alert">Project name is required/);
      assert.doesNotMatch(html, /data-testid="project-row"/);
    }
    const response = await create('  First project  ');
    assert.equal(response.status, 303);
    assert.equal(response.headers.get('location'), '/');
    await create('<Second & project>');
    html = await (await fetch(base)).text();
    assert.equal((html.match(/data-testid="project-row"/g) || []).length, 2);
    assert.match(html, /<span>First project<\/span>/);
    assert.ok(html.indexOf('First project') < html.indexOf('&lt;Second &amp; project&gt;'));
    const paths = [...html.matchAll(/action="(\/projects\/\d+)"/g)].map(match => match[1]);
    assert.equal(paths.length, 2);
    assert.equal((html.match(/data-testid="project-summary">0\/0 completed/g) || []).length, 2);
    assert.equal((html.match(/>Archive project<\/button>/g) || []).length, 2);
    const detail = await (await fetch(base + paths[0])).text();
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /<label for="new-project-name">New project name<\/label>/);
    assert.match(detail, /<input id="new-project-name" name="name" type="text">/);
    assert.match(detail, /<button type="submit">Rename project<\/button>/);
    assert.match(detail, /action="\/".*button type="submit">Projects/);
    assert.equal((await fetch(`${base}/projects/999999`)).status, 404);
    async function postTask(path, values) {
      return fetch(base + path, {
        method: 'POST', body: new URLSearchParams(values), redirect: 'manual'
      });
    }
    const taskPath = `${paths[0]}/tasks`;
    for (const title of ['', '  \t\n ']) {
      const invalid = await postTask(taskPath, { title });
      const invalidHtml = await invalid.text();
      assert.match(invalidHtml, /role="alert">Task title is required/);
      assert.doesNotMatch(invalidHtml, /data-testid="task-row"/);
    }
    assert.equal((await postTask(taskPath, { title: '  First task  ' })).status, 303);
    await postTask(taskPath, { title: '<Second & task>' });
    let tasksHtml = await (await fetch(base + paths[0])).text();
    assert.match(tasksHtml, /<label for="task-title">Task title<\/label>/);
    assert.match(tasksHtml, /<label for="task-filter">Task filter<\/label>/);
    assert.match(tasksHtml, /<option selected>All<\/option><option>Open<\/option><option>Completed<\/option>/);
    assert.match(tasksHtml, /aria-label="Complete First task"/);
    assert.match(tasksHtml, /<span>First task<\/span>/);
    assert.equal((tasksHtml.match(/>New task title<\/label>/g) || []).length, 2);
    assert.equal((tasksHtml.match(/>Rename task<\/button>/g) || []).length, 2);
    assert.doesNotMatch(tasksHtml, / checked/);
    assert.equal((tasksHtml.match(/data-testid="task-row"/g) || []).length, 2);
    assert.ok(tasksHtml.indexOf('First task') < tasksHtml.indexOf('&lt;Second &amp; task&gt;'));
    const completionPath = [...tasksHtml.matchAll(/action="(\/projects\/\d+\/tasks\/\d+)"/g)][0][1];
    assert.equal((await postTask(completionPath, { completed: '1' })).status, 303);
    tasksHtml = await (await fetch(base + paths[0])).text();
    assert.match(tasksHtml, /aria-label="Complete First task" checked/);
    assert.match(await (await fetch(base)).text(), /data-testid="project-summary">1\/2 completed/);
    const openHtml = await (await fetch(base + paths[0] + '?filter=Open')).text();
    assert.doesNotMatch(openHtml, /Complete First task/);
    assert.match(openHtml, /Complete &lt;Second &amp; task&gt;/);
    const completedHtml = await (await fetch(base + paths[0] + '?filter=Completed')).text();
    assert.match(completedHtml, /Complete First task/);
    assert.doesNotMatch(completedHtml, /Complete &lt;Second &amp; task&gt;/);
    assert.doesNotMatch(await (await fetch(base + paths[1])).text(), /data-testid="task-row"/);
    const foreignTaskPath = completionPath.replace(paths[0], paths[1]);
    assert.equal((await postTask(foreignTaskPath, {})).status, 404);
    await stop();
    await start();
    assert.equal(await (await fetch(base + paths[0])).text(), tasksHtml);
    await postTask(completionPath, {});
    assert.doesNotMatch(await (await fetch(base + paths[0])).text(), / checked/);
    await stop();
    await start();
    assert.doesNotMatch(await (await fetch(base + paths[0])).text(), / checked/);
    const reloaded = await (await fetch(base)).text();
    assert.equal(reloaded, html.replace('0/0 completed', '0/2 completed'));
    assert.match(await (await fetch(base + paths[0])).text(), /<h1>First project<\/h1>/);

    await postTask(completionPath, { completed: '1' });
    assert.equal((await postTask(paths[0] + '/archive', {})).status, 303);
    const activeHtml = await (await fetch(base)).text();
    assert.doesNotMatch(activeHtml, /First project/);
    assert.match(activeHtml, /&lt;Second &amp; project&gt;/);
    const archivedHtml = await (await fetch(base + '/?filter=Archived')).text();
    assert.match(archivedHtml, /<option selected>Archived<\/option>/);
    assert.match(archivedHtml, /First project/);
    assert.match(archivedHtml, /data-testid="project-summary">1\/2 completed/);
    assert.match(archivedHtml, />Open project<\/button>/);
    assert.match(archivedHtml, />Restore project<\/button>/);
    assert.doesNotMatch(archivedHtml, />Archive project<\/button>/);
    const archivedDetail = await (await fetch(base + paths[0])).text();
    assert.match(archivedDetail, /Archived project/);
    assert.match(archivedDetail, /<input id="new-project-name" name="name" type="text" disabled>/);
    assert.match(archivedDetail, /<button type="submit" disabled>Rename project/);
    assert.equal((await postTask(paths[0] + '/rename', { name: 'Blocked rename' })).status, 403);
    assert.equal(await (await fetch(base + paths[0])).text(), archivedDetail);
    assert.match(archivedDetail, /<button type="submit" disabled>Create task/);
    assert.equal((archivedDetail.match(/name="title" type="text" disabled/g) || []).length, 2);
    assert.equal((archivedDetail.match(/disabled>Rename task/g) || []).length, 2);
    assert.equal((await postTask(completionPath + '/rename', { title: 'Blocked rename' })).status, 403);
    assert.equal(await (await fetch(base + paths[0])).text(), archivedDetail);
    assert.equal((archivedDetail.match(/type="checkbox"[^>]* disabled/g) || []).length, 2);
